#!/usr/bin/env bash
set -euo pipefail

usage() { echo "usage: {{script_name}} [-i input] [-o output] [-v]"; exit 1; }

input=""; output=""; verbose=0
while getopts ":i:o:vh" opt; do
  case "$opt" in
    i) input="$OPTARG" ;;
    o) output="$OPTARG" ;;
    v) verbose=1 ;;
    h|*) usage ;;
  esac
done

[[ -z "$input" || -z "$output" ]] && usage
[[ $verbose -eq 1 ]] && echo "in=$input out=$output"
cp "$input" "$output"
